const schema={required:['id','amount'],types:{id:'string',amount:'number'}};
const doc={id:42,extra:'x'}; // id wrong type, amount missing
function validate(d){
  const errs=[];
  for(const k of schema.required) if(!(k in d)) errs.push({path:k,rule:'required',fix:'Add "'+k+'" to the document.'});
  for(const k in schema.types) if(k in d&&typeof d[k]!==schema.types[k])
    errs.push({path:k,rule:'type must be '+schema.types[k],fix:'Change '+k+' to a '+schema.types[k]+'.'});
  return errs.length?{decision:'REFUSE',code:'SCHEMA-VALIDATION-FAILED',violations:errs,schema:'invoice-schema v3'}:{decision:'ACCEPT'};
}
console.log(JSON.stringify(validate(doc),null,1));

